    '    def __str__(self) -> str:\n'
    '        """\n'
    '        返回可直接用于 API 和数据库的规范值。\n'
    '        """\n'
    '        return self.value\n'
    '\n'
    '    @classmethod\n'
    '    def _missing_(cls, value: object) -> Optional["MediaSource"]:\n'
    '        """\n'
    '        将合法插件来源标识解析为动态枚举成员，并规范化内置别名。\n'
    '        """\n'
    '        if not isinstance(value, str):\n'
    '            return None\n'
    '        normalized = value.strip().casefold()\n'
    '        normalized = _MEDIA_SOURCE_VALUE_ALIASES.get(normalized, normalized)\n'
    '        known_member = cls._value2member_map_.get(normalized)\n'
    '        if isinstance(known_member, cls):\n'
    '            return known_member\n'
    '        if not _MEDIA_SOURCE_IDENTIFIER_RE.fullmatch(normalized):\n'
    '            return None\n'
    '        member = str.__new__(cls, normalized)\n'
    '        member._name_ = normalized\n'
    '        member._value_ = normalized\n'
    '        known_member = cls._value2member_map_.setdefault(normalized, member)\n'
