    '        在 OpenAPI 中声明可扩展标识格式，避免把内置成员误写成完整白名单。\n'
    '        """\n'
    '        schema: dict[str, object] = handler(core_schema)\n'
    '        schema.pop("enum", None)\n'
    '        schema["pattern"] = MEDIA_SOURCE_IDENTIFIER_PATTERN\n'
    '        schema["examples"] = [source.value for source in cls]\n'
    '        return schema\n'
