    '\n'
    'class NameValueEnum(Enum):\n'
    '    """\n'
    '    支持通过 name 或 value 实例化的枚举基类。\n'
    '    """\n'
    '\n'
    '    @classmethod\n'
    '    def _missing_(cls, value: object) -> Optional["NameValueEnum"]:\n'
    '        """\n'
    '        在直接按值查找失败后，尝试按忽略大小写的成员名称匹配。\n'
    '\n'
    '        :param value: 待匹配的枚举名称或值\n'
    '        :return: 匹配成员，非字符串或没有匹配项时返回 None\n'
    '        """\n'
    '        if isinstance(value, str):\n'
    '            for member in cls:\n'
    '                if member.name.lower() == value.lower() or member.value == value:\n'
    '                    return member\n'
    '        return None\n'
    '\n'
    '\n'
    '# 刮削策略\n'
