    '\n'
    '        logger.error(f"[GitHub] 所有策略均请求失败，URL: {url}，请检查网络连接或 GitHub 配置")\n'
    '        return None\n'
    '\n'
    '    @staticmethod\n'
    '    async def async_request_with_fallback(\n'
    '        url: str,\n'
    '        *,\n'
    '        headers: Optional[dict[str, str]] = None,\n'
    '        timeout: Optional[int] = 60,\n'
    '        is_api: bool = False,\n'
    '        mirror_url: Optional[str] = None,\n'
    '    ) -> Optional[httpx2.Response]:\n'
    '        """\n'
    '        向包来源客户端公开既有异步 GitHub 降级传输。\n'
    '\n'
    '        :param mirror_url: 可选的公开 Release 资产地址，失败后保留原 API 出口\n'
    '        """\n'
    '        return await PluginMarketTransport.__async_request_with_fallback(\n'
    '            url, headers=headers, timeout=timeout, is_api=is_api, mirror_url=mirror_url\n'
    '        )\n'
    '\n'
    '    @cached(maxsize=256, ttl=300, skip_none=False, local_only=True)\n'
    '    async def async_get_plugin_readme_url(\n'
    '        self, pid: str, repo_url: str, package_version: Optional[str]\n'
    '    ) -> Optional[str]:\n'
    '        """\n'
    '        沿用 GitHub 代理策略探测 README，只读取响应头并缓存存在与缺失结果。\n'
    '\n'
    '        :param pid: 市场索引中的源插件 ID\n'
    '        :param repo_url: 已由目录确认的 GitHub 仓库地址\n'
    '        :param package_version: 实际候选代际，基础索引使用 None 或空字符串\n'
    '        :return: 可在浏览器打开的 README 地址；缺失或短超时后返回 None\n'
    '        """\n'
    '        normalized_repo = normalize_plugin_market_repo_url(repo_url)\n'
    '        if not normalized_repo or not is_physical_plugin_id(pid):\n'
    '            return None\n'
    '        if package_version and not PLUGIN_INDEX_COMPATIBILITY_FLAG_PATTERN.fullmatch(package_version):\n'
    '            return None\n'
    '        user, repo = self.get_repo_info(normalized_repo)\n'
    '        directory = f"plugins.{package_version}" if package_version and package_version != "v1" else "plugins"\n'
    '        path = f"{directory}/{pid.lower()}/README.md"\n'
    '        raw_url = f"{self._base_url.format(user=user, repo=repo)}{path}"\n'
    '        headers = get_runtime_setting(\'REPO_GITHUB_HEADERS\')(repo=f"{user}/{repo}")\n'
    '        strategies = self._build_github_request_strategies(\n'
    '            raw_url, headers=headers, timeout=PLUGIN_README_REQUEST_TIMEOUT,\n'
    '        )\n'
    '        try:\n'
    '            async with asyncio.timeout(PLUGIN_README_REQUEST_TIMEOUT):\n'
    '                for _strategy, target_url, options in strategies:\n'
    '                    try:\n'
    '                        if await self._async_plugin_readme_exists(target_url, options):\n'
    '                            return f"{normalized_repo}/blob/main/{path}"\n'
    '                    except Exception as error:  # noqa: BLE001\n'
    '                        logger.debug(f"探测插件 {pid} README 失败：{_format_request_error(error)}")\n'
    '        except TimeoutError:\n'
    '            logger.debug(f"探测插件 {pid} README 超时")\n'
    '        return None\n'
    '\n'
    '    @staticmethod\n'
    '    async def _async_plugin_readme_exists(url: str, options: PluginRequestOptions) -> bool:\n'
    '        """\n'
    '        流式检查 README 响应头，拒绝镜像验证页，不下载文档正文。\n'
    '\n'
    '        :param url: GitHub 原始文件地址或既有配置中的镜像地址\n'
    '        :param options: 代理策略提供的鉴权、出口和短超时参数\n'
    '        :return: 响应成功且不是 HTML 时为 True；传输异常交由外层降级处理\n'
    '        """\n'
    '        async with AsyncRequestUtils(**options).get_stream(url=url, raise_exception=True) as response:\n'
    '            return bool(\n'
    '                response is not None and response.status_code == 200\n'
    '                and "text/html" not in response.headers.get("content-type", "").lower()\n'
    '            )\n'
    '\n'
    '    async def __async_get_plugin_meta(\n'
    '        self, pid: str, repo_url: str, package_version: Optional[str]\n'
    '    ) -> PluginPayload:\n'
    '        """\n'
    '        异步读取远端插件元数据，供兼容性查询保留旧私有入口。\n'
    '        """\n'
    '        try:\n'
    '            plugins = await self.async_get_plugins(\n'
    '                repo_url, package_version or None\n'
    '            ) or {}\n'
    '            meta = plugins.get(pid)\n'
    '            return meta if isinstance(meta, dict) else {}\n'
    '        except Exception as error:\n'
    '            logger.warning(f"获取插件 {pid} 元数据失败：{error}")\n'
    '            return {}\n'
    '\n'
    '    @cached(maxsize=1024, ttl=1800, skip_none=False)\n'
    '    async def async_get_plugin_index_result(\n'
    '            self,\n'
    '            repo_url: str,\n'
    '            package_version: Optional[str] = None,\n'
    '    ) -> Optional[PluginIndex]:\n'
    '        """\n'
    '        异步读取插件索引；404 返回 None，读取失败由调用方记录。\n'
    '        """\n'
    '        request = self._build_plugin_index_request(repo_url, package_version)\n'
    '        if request is None:\n'
    '            raise ValueError("插件仓库地址无效")\n'
    '        package_url, headers = request\n'
    '        repo_key, generation_key = self._plugin_index_key(\n'
    '            repo_url,\n'
    '            package_version,\n'
    '        )\n'
    '        loop = asyncio.get_running_loop()\n'
    '        task_key = (loop, repo_key, generation_key)\n'
    '        with self._index_task_lock:\n'
    '            task = self._index_tasks.get(task_key)\n'
    '            if task is None:\n'
    '                task = cast(\n'
    '                    asyncio.Task[PluginIndexTaskResult],\n'
    '                    get_task_registry().create(\n'
    '                        self._fetch_plugin_index_async_task(\n'
    '                            package_url,\n'
    '                            headers,\n'
    '                        ),\n'
    '                        owner="plugin.market.index",\n'
    '                    ),\n'
    '                )\n'
    '                self._index_tasks[task_key] = task\n'
    '\n'
    '                def on_index_task_done(\n'
    '                    completed_task: asyncio.Future[PluginIndexTaskResult],\n'
    '                ) -> None:\n'
    '                    """\n'
    '                    共享索引请求结束后移除对应任务登记，避免保留已完成任务。\n'
    '                    """\n'
    '                    self._remove_index_task(task_key, completed_task)\n'
    '\n'
    '                task.add_done_callback(on_index_task_done)\n'
    '\n'
    '        # 单个调用方取消等待时不能连带取消共享请求。\n'
    '        result, error = await asyncio.shield(task)\n'
    '        if error is not None:\n'
    '            raise error\n'
    '        return result\n'
    '\n'
    '    async def async_get_plugins(self, repo_url: str,\n'
    '                                package_version: Optional[str] = None) -> Optional[PluginIndex]:\n'
    '        """\n'
    '        异步获取 Github 插件列表，保留旧的 dict/{}/None 兼容返回。\n'
    '\n'
    '        :param repo_url: Github仓库地址\n'
    '        :param package_version: 首选插件版本 (如 "v2", "v3")，如果不指定则获取 v1 版本\n'
    '        """\n'
    '        try:\n'
    '            payload = await self.async_get_plugin_index_result(\n'
    '                repo_url,\n'
    '                package_version,\n'
    '            )\n'
    '        except (ValueError, RuntimeError):\n'
    '            return None\n'
    '        return payload if payload is not None else {}\n'
    '\n'
    '    @cached(maxsize=256, ttl=1800, shared_key="get_plugin_repo_releases")\n'
    '    async def _async_get_plugin_repo_releases(\n'
    '        self, repo_url: str\n'
    '    ) -> Optional[PluginReleaseList]:\n'
    '        """\n'
    '        异步按仓库获取 GitHub Release 原始分页数据。\n'
    '        """\n'
    '        releases: PluginReleaseList = []\n'
    '        for release_api, headers in self._iter_plugin_release_page_requests(\n'
    '                repo_url\n'
    '        ):\n'
    '            res = await self.__async_request_with_fallback(\n'
    '                release_api,\n'
    '                headers=headers,\n'
    '                timeout=30,\n'
    '                is_api=True,\n'
    '            )\n'
    '            should_continue = self._merge_plugin_release_page(\n'
    '                repo_url,\n'
    '                res,\n'
    '                releases,\n'
    '            )\n'
    '            if should_continue is None:\n'
    '                return None\n'
    '            if not should_continue:\n'
    '                break\n'
    '        return releases\n'
    '\n'
    '    async def async_get_plugin_release_versions(\n'
    '        self, pid: str, repo_url: str\n'
    '    ) -> PluginReleaseList:\n'
    '        """\n'
    '        异步获取插件可安装的 GitHub Release 版本列表。\n'
    '\n'
    '        同一事件循环内，同仓库的并发读取和强制刷新共享一个请求任务。\n'
    '        """\n'
    '        if not pid or not repo_url:\n'
    '            return []\n'
    '\n'
    '        loop = asyncio.get_running_loop()\n'
    '        normalized_repo_url = repo_url.rstrip("/")\n'
    '        normal_task_key = (loop, normalized_repo_url, False)\n'
    '        force_task_key = (loop, normalized_repo_url, True)\n'
    '        with self._release_task_lock:\n'
    '            if is_fresh():\n'
    '                force_task = self._release_tasks.get(force_task_key)\n'
    '                if force_task and not force_task.done():\n'
    '                    task_key = force_task_key\n'
    '                    task = force_task\n'
    '                else:\n'
    '                    pending_normal_task = self._release_tasks.get(normal_task_key)\n'
    '                    if pending_normal_task and pending_normal_task.done():\n'
    '                        pending_normal_task = None\n'
    '                    task_key = force_task_key\n'
    '                    task = get_task_registry().create(\n'
    '                        self._async_refresh_plugin_repo_releases(\n'
    '                            normalized_repo_url,\n'
    '                            pending_normal_task,\n'
    '                        ),\n'
    '                        owner="plugin.market.release_refresh",\n'
    '                    )\n'
    '                    self._release_tasks[task_key] = task\n'
    '                    task.add_done_callback(\n'
    '                        lambda completed_task: self._remove_release_task(task_key, completed_task)\n'
    '                    )\n'
    '            else:\n'
    '                task_key = normal_task_key\n'
    '                pending_normal_task = self._release_tasks.get(normal_task_key)\n'
    '                if pending_normal_task is None or pending_normal_task.done():\n'
    '                    task = get_task_registry().create(\n'
    '                        self._async_get_plugin_repo_releases(normalized_repo_url),\n'
    '                        owner="plugin.market.release_read",\n'
    '                    )\n'
    '                    self._release_tasks[task_key] = task\n'
    '                    task.add_done_callback(\n'
    '                        lambda completed_task: self._remove_release_task(task_key, completed_task)\n'
    '                    )\n'
    '                else:\n'
    '                    task = pending_normal_task\n'
    '\n'
    '        payload = await asyncio.shield(task)\n'
    '        return self.__parse_plugin_release_response(pid, payload)\n'
    '\n'
    '    async def async_has_plugin_release_cache(self, repo_url: str) -> bool:\n'
    '        """\n'
    '        判断指定仓库的 Release 列表缓存是否已经存在。\n'
    '        """\n'
    '        if not repo_url:\n'
    '            return False\n'
    '        return bool(\n'
    '            await cast(AsyncCacheControls, self._async_get_plugin_repo_releases).cache_exists(\n'
    '                self, repo_url.rstrip("/")\n'
    '            )\n'
    '        )\n'
    '\n'
    '    async def _async_refresh_plugin_repo_releases(\n'
    '        self,\n'
    '        repo_url: str,\n'
    '        pending_normal_task: Optional[PluginReleaseTask],\n'
    '    ) -> Optional[PluginReleaseList]:\n'
    '        """\n'
    '        等待在途普通读取落盘后执行强刷，确保旧结果不会覆盖强刷缓存。\n'
    '        """\n'
    '        if pending_normal_task:\n'
    '            try:\n'
    '                await asyncio.shield(pending_normal_task)\n'
    '            except (Exception, asyncio.CancelledError):\n'
    '                pass\n'
    '        return await self._async_get_plugin_repo_releases(repo_url)\n'
    '\n'
    '    @classmethod\n'
    '    def _remove_release_task(\n'
    '        cls,\n'
    '        task_key: tuple[asyncio.AbstractEventLoop, str, bool],\n'
    '        task: PluginReleaseTask,\n'
    '    ) -> None:\n'
    '        """\n'
    '        请求任务完成后释放事件循环和仓库引用。\n'
    '        """\n'
    '        with cls._release_task_lock:\n'
    '            if cls._release_tasks.get(task_key) is task:\n'
    '                cls._release_tasks.pop(task_key, None)\n'
    '\n'
    '\n'
    'class PluginMarketClient:\n'
    '    """\n'
    '    把插件市场、版本元数据和本地仓库查询隔离为只读客户端。\n'
    '    """\n'
    '\n'
    '    def __init__(self, transport: Optional[PluginMarketTransport] = None) -> None:\n'
    '        """\n'
    '        保存索引传输端口；默认实现必须先由兼容市场模块显式注册。\n'
    '        """\n'
    '        self._transport = transport or PluginMarketTransport()\n'
    '\n'
    '    def get_plugins(\n'
    '        self,\n'
    '        repo_url: str,\n'
    '        package_version: Optional[str] = None,\n'
    '        force: bool = False,\n'
    '    ) -> Optional[PluginIndex]:\n'
    '        """\n'
    '        同步读取指定仓库和代际的插件索引。\n'
    '        """\n'
    '        with fresh(force):\n'
    '            return self._transport.get_plugins(repo_url, package_version)\n'
    '\n'
    '    async def async_get_plugins(\n'
    '        self,\n'
    '        repo_url: str,\n'
    '        package_version: Optional[str] = None,\n'
    '        force: bool = False,\n'
    '    ) -> Optional[PluginIndex]:\n'
    '        """\n'
    '        异步读取指定仓库和代际的插件索引。\n'
    '        """\n'
    '        async with async_fresh(force):\n'
    '            return await self._transport.async_get_plugins(repo_url, package_version)\n'
    '\n'
    '    def get_plugin_index_result(\n'
    '        self,\n'
    '        repo_url: str,\n'
    '        package_version: Optional[str] = None,\n'
    '        force: bool = False,\n'
    '    ) -> Optional[PluginIndex]:\n'
    '        """\n'
    '        读取插件索引的三态结果，供库存读取保留失败事实。\n'
    '        """\n'
    '        with fresh(force):\n'
    '            return self._transport.get_plugin_index_result(repo_url, package_version)\n'
    '\n'
    '    async def async_get_plugin_index_result(\n'
    '        self,\n'
    '        repo_url: str,\n'
    '        package_version: Optional[str] = None,\n'
    '        force: bool = False,\n'
    '    ) -> Optional[PluginIndex]:\n'
    '        """\n'
    '        异步读取插件索引的三态结果，供库存读取保留失败事实。\n'
    '        """\n'
    '        async with async_fresh(force):\n'
    '            return await self._transport.async_get_plugin_index_result(\n'
    '                    repo_url,\n'
    '                    package_version,\n'
    '                )\n'
    '\n'
    '    def get_local_candidates(self) -> PluginIndex:\n'
    '        """\n'
    '        返回全部本地插件仓库候选。\n'
    '        """\n'
    '        return self._transport.get_local_plugin_candidates()\n'
    '\n'
    '    def get_local_candidate(\n'
    '        self,\n'
    '        plugin_id: str,\n'
    '        package_version: Optional[str] = None,\n'
    '        repo_path: Optional[Path] = None,\n'
    '        **kwargs: Any,\n'
    '    ) -> Optional[PluginPayload]:\n'
    '        """\n'
    '        返回指定插件的本地仓库候选。\n'
    '        """\n'
    '        return self._transport.get_local_plugin_candidate(\n'
    '            pid=plugin_id,\n'
    '            package_version=package_version,\n'
    '            repo_path=repo_path,\n'
    '            **kwargs,\n'
    '        )\n'
    '\n'
    '    @staticmethod\n'
    '    def get_local_repo_paths() -> list[Path]:\n'
    '        """\n'
    '        返回配置中有效的本地插件仓库目录。\n'
    '        """\n'
    "        value = get_runtime_setting('PLUGIN_LOCAL_REPO_PATHS')\n"
    '        if not value:\n'
    '            return []\n'
    "        root_path = Path(get_runtime_setting('ROOT_PATH'))\n"
    '        paths: list[Path] = []\n'
    '        for item in value.split(","):\n'
    '            local_repo_path = item.strip()\n'
    '            if not local_repo_path:\n'
    '                continue\n'
    '            path = Path(local_repo_path).expanduser()\n'
    '            if not path.is_absolute():\n'
    '                path = root_path / path\n'
    '            paths.append(path.resolve())\n'
    '        return paths\n'
    '\n'
    '    @staticmethod\n'
    '    def make_local_repo_url(\n'
    '        plugin_id: str,\n'
    '        repo_path: Optional[object] = None,\n'
    '        package_version: Optional[str] = None,\n'
    '    ) -> str:\n'
    '        """\n'
    '        生成兼容旧入口的本地插件来源标识。\n'
    '        """\n'
    '        return build_local_repo_url(\n'
    '            plugin_id,\n'
    '            repo_path=cast(Optional[Path], repo_path),\n'
    '            package_version=package_version,\n'
    '        )\n'
    '\n'
    '    @staticmethod\n'
    '    def is_local_repo_url(repo_url: Optional[str]) -> bool:\n'
    '        """\n'
    '        判断插件来源是否为本地仓库标识。\n'
    '        """\n'
    '        return is_local_plugin_source(repo_url)\n'
    '\n'
    '    @staticmethod\n'
    '    def annotate_system_version(plugin_info: PluginPayload) -> PluginPayload:\n'
    '        """\n'
    '        补充插件所需 MoviePilot 版本兼容状态。\n'
    '        """\n'
    '        compatible, message = check_plugin_system_version(\n'
    '            plugin_info,\n'
    '            current_version=get_app_version(),\n'
    '        )\n'
    '        plugin_info["system_version_compatible"] = compatible\n'
    '        plugin_info["system_version_message"] = message\n'
    '        return plugin_info\n'
    '\n'
    '    @staticmethod\n'
    '    def annotate_runtime_compatibility(plugin_info: PluginPayload) -> PluginPayload:\n'
    '        """\n'
    '        补充插件声明的运行时兼容状态。\n'
    '        """\n'
    '        compatible, message = check_plugin_runtime_compatibility(\n'
    '            plugin_info,\n'
    '            free_threaded=is_free_threaded_runtime(),\n'
    '        )\n'
    '        plugin_info["runtime_compatible"] = compatible\n'
    '        plugin_info["runtime_message"] = message\n'
    '        return plugin_info\n'
    '\n'
    '    @staticmethod\n'
    '    def is_package_compatible(\n'
    '        plugin_info: PluginPayload,\n'
    '        package_version: Optional[str],\n'
    '    ) -> bool:\n'
    '        """\n'
    '        判断插件条目是否兼容目标插件包代际。\n'
    '        """\n'
    '        return is_plugin_generation_compatible(\n'
    '            plugin_info,\n'
    '            package_version,\n'
    "            current_generation=get_runtime_setting('VERSION_FLAG'),\n"
    '        )\n'
    '\n'
    '\n'
    'class PluginPackageSourceClient:\n'
    '    """\n'
    '    为系统包 owner 提供只读市场元数据和远端制品传输。\n'
    '    """\n'
    '\n'
    '    def __init__(self, transport: Optional[PluginMarketTransport] = None) -> None:\n'
    '        """\n'
    '        保存由组合根注入的市场传输，不导入兼容 Helper 实现。\n'
    '        """\n'
    '        self._transport = transport or PluginMarketTransport()\n'
    '\n'
    '    @staticmethod\n'
    '    def is_local_repo_url(repo_url: Optional[str]) -> bool:\n'
    '        """\n'
    '        判断来源是否为本地仓库标识。\n'
    '        """\n'
    '        return is_local_repo_url(repo_url)\n'
    '\n'
    '    @staticmethod\n'
    '    def parse_local_repo_url(repo_url: str) -> Optional[str]:\n'
    '        """\n'
    '        解析本地仓库来源中的插件标识。\n'
    '        """\n'
    '        return parse_local_repo_plugin_id(repo_url)\n'
    '\n'
    '    @staticmethod\n'
    '    def parse_local_repo_path(repo_url: str) -> Optional[Path]:\n'
    '        """\n'
    '        解析本地仓库来源中的物理路径。\n'
    '        """\n'
    "        root = get_runtime_setting('ROOT_PATH')\n"
    '        return parse_local_repo_path(\n'
    '            repo_url,\n'
    '            root_path=Path(root) if root is not None else None,\n'
    '        )\n'
    '\n'
    '    @staticmethod\n'
    '    def parse_local_repo_package_version(repo_url: str) -> Optional[str]:\n'
    '        """\n'
    '        解析本地仓库来源中的包代际。\n'
    '        """\n'
    '        return parse_local_repo_generation(repo_url)\n'
    '\n'
    '    @staticmethod\n'
    '    def make_local_repo_url(\n'
    '        plugin_id: str,\n'
    '        repo_path: Optional[Path] = None,\n'
    '        package_version: Optional[str] = None,\n'
    '    ) -> str:\n'
    '        """\n'
    '        生成本地仓库来源标识。\n'
    '        """\n'
    '        return build_local_repo_url(\n'
    '            plugin_id,\n'
    '            repo_path=repo_path,\n'
    '            package_version=package_version,\n'
    '        )\n'
    '\n'
    '    def get_local_plugin_candidate(\n'
    '        self,\n'
    '        pid: str,\n'
    '        package_version: Optional[str] = None,\n'
    '        repo_path: Optional[Path] = None,\n'
    '        strict_compat: bool = True,\n'
    '        strict_system_version: bool = True,\n'
    '    ) -> Optional[PluginPayload]:\n'
    '        """\n'
    '        读取一个本地插件候选。\n'
    '        """\n'
    '        return self._transport.get_local_plugin_candidate(\n'
    '            pid=pid,\n'
    '            package_version=package_version,\n'
    '            repo_path=repo_path,\n'
    '            strict_compat=strict_compat,\n'
    '            strict_system_version=strict_system_version,\n'
    '        )\n'
    '\n'
    '    @staticmethod\n'
    '    def check_plugin_system_version(\n'
    '        plugin_info: PluginPayload,\n'
    '    ) -> tuple[bool, str]:\n'
    '        """\n'
    '        校验插件声明的宿主版本约束。\n'
    '        """\n'
    '        return check_plugin_system_version(\n'
    '            plugin_info, current_version=get_app_version()\n'
    '        )\n'
    '\n'
    '    @staticmethod\n'
    '    def check_plugin_install_compatibility(\n'
    '        plugin_info: PluginPayload,\n'
    '    ) -> tuple[bool, str]:\n'
    '        """\n'
    '        安装准入的唯一兼容判据：先判运行时，再判宿主版本。\n'
    '        """\n'
    '        compatible, message = check_plugin_runtime_compatibility(\n'
    '            plugin_info,\n'
    '            free_threaded=is_free_threaded_runtime(),\n'
    '        )\n'
    '        if not compatible:\n'
    '            return compatible, message\n'
    '        return check_plugin_system_version(\n'
    '            plugin_info, current_version=get_app_version()\n'
    '        )\n'
    '\n'
    '    def get_plugin_package_version(\n'
    '        self,\n'
    '        plugin_id: str,\n'
    '        repo_url: str,\n'
    '        package_version: Optional[str],\n'
    '    ) -> Optional[str]:\n'
    '        """\n'
    '        选择适用于当前宿主的远端索引代际。\n'
    '        """\n'
    '        return self._transport.get_plugin_package_version(\n'
    '            plugin_id, repo_url, package_version\n'
    '        )\n'
    '\n'
    '    async def async_get_plugin_package_version(\n'
    '        self,\n'
    '        plugin_id: str,\n'
    '        repo_url: str,\n'
    '        package_version: Optional[str],\n'
    '    ) -> Optional[str]:\n'
    '        """\n'
    '        异步选择适用于当前宿主的远端索引代际。\n'
    '        """\n'
    '        return await self._transport.async_get_plugin_package_version(\n'
    '            plugin_id, repo_url, package_version\n'
    '        )\n'
    '\n'
    '    def get_plugins(\n'
    '        self, repo_url: str, package_version: Optional[str] = None\n'
    '    ) -> Optional[PluginIndex]:\n'
    '        """\n'
    '        读取远端插件索引。\n'
    '        """\n'
    '        return self._transport.get_plugins(repo_url, package_version)\n'
    '\n'
    '    async def async_get_plugins(\n'
    '        self, repo_url: str, package_version: Optional[str] = None\n'
    '    ) -> Optional[PluginIndex]:\n'
    '        """\n'
    '        异步读取远端插件索引。\n'
    '        """\n'
    '        return await self._transport.async_get_plugins(repo_url, package_version)\n'
    '\n'
    '    def get_plugin_release_versions(\n'
    '        self, plugin_id: str, repo_url: str\n'
    '    ) -> list[dict[str, Any]]:\n'
    '        """\n'
    '        读取插件可安装 Release。\n'
    '        """\n'
    '        return self._transport.get_plugin_release_versions(plugin_id, repo_url)\n'
    '\n'
    '    async def async_get_plugin_release_versions(\n'
    '        self, plugin_id: str, repo_url: str\n'
    '    ) -> list[dict[str, Any]]:\n'
    '        """\n'
    '        异步读取插件可安装 Release。\n'
    '        """\n'
    '        return await self._transport.async_get_plugin_release_versions(\n'
    '            plugin_id, repo_url\n'
    '        )\n'
    '\n'
    '    @staticmethod\n'
    '    def get_repo_info(repo_url: str) -> tuple[Optional[str], Optional[str]]:\n'
    '        """\n'
    '        解析 GitHub 仓库所有者和仓库名。\n'
    '        """\n'
    '        if not repo_url:\n'
    '            return None, None\n'
    '        parts = repo_url.rstrip("/").split("/")\n'
    '        if len(parts) < 5:\n'
    '            return None, None\n'
    '        return parts[-2], parts[-1]\n'
    '\n'
    '    def request(\n'
    '        self,\n'
    '        url: str,\n'
    '        *,\n'
    '        headers: Optional[dict[str, str]] = None,\n'
    '        timeout: Optional[int] = 60,\n'
    '        is_api: bool = False,\n'
    '        mirror_url: Optional[str] = None,\n'
    '    ) -> Any:\n'
    '        """\n'
    '        同步读取 GitHub 元数据或制品。\n'
    '\n'
    '        :param mirror_url: 可选的公开 Release 资产地址，镜像使用匿名请求\n'
    '        """\n'
    '        return self._transport.request_with_fallback(\n'
    '            url, headers=headers, timeout=timeout, is_api=is_api, mirror_url=mirror_url\n'
    '        )\n'
    '\n'
    '    async def async_request(\n'
    '        self,\n'
    '        url: str,\n'
    '        *,\n'
    '        headers: Optional[dict[str, str]] = None,\n'
    '        timeout: Optional[int] = 60,\n'
    '        is_api: bool = False,\n'
    '        mirror_url: Optional[str] = None,\n'
    '    ) -> Any:\n'
    '        """\n'
    '        异步读取 GitHub 元数据或制品。\n'
    '\n'
    '        :param mirror_url: 可选的公开 Release 资产地址，镜像使用匿名请求\n'
    '        """\n'
    '        return await self._transport.async_request_with_fallback(\n'
    '            url, headers=headers, timeout=timeout, is_api=is_api, mirror_url=mirror_url\n'
    '        )\n'
    '\n'
    '\n'
    'setattr(\n'
    '    PluginMarketTransport.get_plugin_release_versions,\n'
    '    "cache_clear",\n'
    '    getattr(PluginMarketTransport._get_plugin_repo_releases, "cache_clear"),\n'
    ')\n'
    'setattr(\n'
    '    PluginMarketTransport.get_plugin_release_versions,\n'
    '    "cache_region",\n'
    '    getattr(PluginMarketTransport._get_plugin_repo_releases, "cache_region"),\n'
    ')\n'
    'setattr(\n'
    '    PluginMarketTransport.async_get_plugin_release_versions,\n'
    '    "cache_clear",\n'
    '    getattr(PluginMarketTransport._async_get_plugin_repo_releases, "cache_clear"),\n'
    ')\n'
    'setattr(\n'
    '    PluginMarketTransport.async_get_plugin_release_versions,\n'
    '    "cache_region",\n'
    '    getattr(PluginMarketTransport._async_get_plugin_repo_releases, "cache_region"),\n'
    ')\n'
